from collections import deque

def flood_fill(grid, start, color, blocked=None):
    if blocked is None:
        blocked = set()
    output = [row[:] for row in grid]
    queue = deque([start])
    visited = {start}

    while queue:
        r, c = queue.popleft()
        output[r][c] = color
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < 25 and 0 <= nc < 24 and (nr, nc) not in visited:
                if output[nr][nc] in [6] and input_grid[nr][nc] not in blocked if isinstance(blocked, set) else True:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return output

# Try simpler: just mark 5s as 2, 3s as 1, remove 6 and 9
# But ensure consistency within each "region"

output_grid = [[0 for _ in range(24)] for _ in range(25)]

for r in range(25):
    for c in range(24):
        if input_grid[r][c] == 3:
            output_grid[r][c] = 1
        elif input_grid[r][c] == 5:
            output_grid[r][c] = 2
        elif input_grid[r][c] == 9:
            output_grid[r][c] = 0  # Remove 9s
        else:  # 6
            output_grid[r][c] = 0

print("Simple remap: 3->1, 5->2, 6->0, 9->0")
